import { createHash } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";
import { kinoSnapshotSchema, type KinoSnapshot } from "../lib/super-kino.ts";
import { orderBudgetTickets, prepareBudgetEvaluator } from "../lib/kino-budget-study.ts";
import { summarizeStability } from "../lib/kino-budget-stability.ts";
import { exactTicketEconomics } from "../lib/kino-portfolio-risk.ts";
import { randomStream, sampleBalls } from "../lib/kino-bowl-lab.ts";

const runId = process.argv[2] ?? "seven-snapshots-2026-11-14";
if (process.argv.length > 3 || !/^[a-zA-Z0-9_-]+$/.test(runId)) throw new Error("Use a simple run-id");
const dates = [2, 4, 6, 8, 10, 12, 14].map(n => `2026-11-${String(n).padStart(2, "0")}`), seeds = [0, 1, 2], budgets = [20, 50, 100, 200], iterations = 20_000;
const inputs: { date: string; path: string; raw: string; snapshot: KinoSnapshot; sha256: string }[] = [];
for (const date of dates) {
  const path = `data/super-kino-portfolios/${date}.json`, raw = await readFile(path, "utf8"), snapshot = kinoSnapshotSchema.parse(JSON.parse(raw));
  if (snapshot.targetDate !== date || snapshot.algorithm !== "kino-v13.3" || snapshot.plays.length !== 200) throw new Error(`Unexpected snapshot ${date}`);
  inputs.push({ date, path, raw, snapshot, sha256: createHash("sha256").update(raw).digest("hex") });
}
if (inputs.some(i => JSON.stringify(i.snapshot.prizes) !== JSON.stringify(inputs[0].snapshot.prizes))) throw new Error("Prize tables differ");
const protocol = await readFile("docs/experimentos/super-kino/estabilidad-presupuesto-v1/PROTOCOLO.md", "utf8"), codeHash = createHash("sha256");
const sources: { path: string; content: string }[] = [];
for (const path of ["scripts/audit-kino-budget-stability.ts", "lib/kino-budget-stability.ts", "lib/kino-budget-study.ts", "lib/kino-portfolio-risk.ts", "lib/kino-bowl-lab.ts", "lib/kino-math.ts", "lib/kino-experiment-strategies.ts", "lib/super-kino.ts", "lib/super-kino-v133.ts"]) {
  const content = await readFile(path, "utf8"); sources.push({ path, content }); codeHash.update(path).update(content);
}
const metadata = { version: "kino-budget-stability-v1", dates, seeds, budgets, iterationsPerPair: iterations, totalSyntheticDraws: dates.length * seeds.length * iterations,
  codeSha256: codeHash.digest("hex"), protocolSha256: createHash("sha256").update(protocol).digest("hex"), inputs: inputs.map(({ date, path, sha256 }) => ({ date, path, sha256 })), generatedAt: new Date().toISOString(), node: process.version, operationalWrites: false };
const out = resolve("experiments/super-kino/estabilidad-presupuesto-v1", runId);
await mkdir(resolve(out, ".."), { recursive: true }); await mkdir(out);
await writeFile(resolve(out, "protocol.md"), protocol);
await writeFile(resolve(out, "sources.json"), JSON.stringify(sources));
await writeFile(resolve(out, "inputs.json"), JSON.stringify(inputs.map(({ date, path, raw, sha256 }) => ({ date, path, raw, sha256 }))));
await writeFile(resolve(out, "metadata.json"), JSON.stringify(metadata, null, 2));

function evaluatePair(date: string, snapshot: KinoSnapshot, seed: number) {
  const subsetSeed = `kino-budget-stability-v1/subset/${date}/${seed}`, drawSeed = `kino-budget-stability-v1/draws/${date}/${seed}`;
  const tickets = snapshot.plays.map(p => p.numbers), modes = ["random", "coverage"] as const;
  const orders = modes.map(mode => orderBudgetTickets(tickets, mode, subsetSeed));
  const evaluate = orders.map(order => prepareBudgetEvaluator(order.map(i => tickets[i]), budgets, snapshot.prizes));
  const counts = modes.map(() => budgets.map(() => ({ seven: 0, eight: 0, loss: 0 })));
  const differences = budgets.map(() => ({ sum: 0, squares: 0 }));
  const rng = randomStream(drawSeed), weights = Array<number>(84).fill(1);
  for (let i = 0; i < iterations; i++) {
    const winning = sampleBalls(rng, weights), evaluated = evaluate.map(fn => fn(winning));
    if (evaluated[0][3].maxHits !== evaluated[1][3].maxHits || evaluated[0][3].gross !== evaluated[1][3].gross) throw new Error("Full portfolio mismatch");
    evaluated.forEach((rows, m) => rows.forEach((row, k) => {
      const a = counts[m][k]; a.seven += Number(row.maxHits >= 7); a.eight += Number(row.maxHits >= 8); a.loss += Number(row.gross < budgets[k] * 25);
      if (m === 1) {
        const d = Number(row.maxHits >= 7) - Number(evaluated[0][k].maxHits >= 7);
        differences[k].sum += d; differences[k].squares += d * d;
      }
    }));
  }
  return { date, seed, subsetSeed, drawSeed, orders, budgets: budgets.map((budget, k) => {
    const mean = differences[k].sum / iterations, se = Math.sqrt(Math.max(0, differences[k].squares - iterations * mean * mean) / (iterations - 1) / iterations);
    return { budget, randomRate: counts[0][k].seven / iterations, coverageRate: counts[1][k].seven / iterations,
      randomEightRate: counts[0][k].eight / iterations, coverageEightRate: counts[1][k].eight / iterations,
      randomLossRate: counts[0][k].loss / iterations, coverageLossRate: counts[1][k].loss / iterations,
      coverageRetainedSeven: counts[1][k].seven / counts[1][3].seven,
      pairedMonteCarloDifference: mean, pairedMonteCarloCi95: [mean - 1.96 * se, mean + 1.96 * se] };
  }) };
}
const pairs: ReturnType<typeof evaluatePair>[] = [];
for (const input of inputs) for (const seed of seeds) {
  console.log(`Evaluating snapshot ${input.date}, subset seed ${seed}, ${iterations} draws`);
  pairs.push(evaluatePair(input.date, input.snapshot, seed));
}
const clusterRows = pairs.flatMap(pair => pair.budgets.filter(r => r.budget < 200).map(r => ({ date: pair.date, seed: pair.seed, budget: r.budget, randomRate: r.randomRate, coverageRate: r.coverageRate })));
const cluster = summarizeStability(clusterRows, "kino-budget-stability-v1/bootstrap");
const economics = exactTicketEconomics(inputs[0].snapshot.prizes);
const budgetSummary = budgets.map(budget => {
  const rows = pairs.map(p => p.budgets.find(r => r.budget === budget)!);
  const mean = (fn: (r: typeof rows[number]) => number) => rows.reduce((s, r) => s + fn(r), 0) / rows.length;
  return { budget, cost: budget * economics.ticketCost, expectedNet: budget * economics.expectedNetPerTicket,
    randomSevenRate: mean(r => r.randomRate), coverageSevenRate: mean(r => r.coverageRate), coverageEightRate: mean(r => r.coverageEightRate), coverageLossRate: mean(r => r.coverageLossRate), coverageRetainedSeven: mean(r => r.coverageRetainedSeven) };
});
const decision = cluster.some(r => r.passesExploratoryGate) ? "Exploratory gate passed in at least one budget; requires new portfolio validation, no adoption" : "No budget passed the exploratory stability gate; no demonstrated advantage, not equivalence";
await writeFile(resolve(out, "report.json"), JSON.stringify({ metadata, economics, cluster, budgetSummary, pairs, decision }, null, 2));
const pct = (p: number) => `${(100 * p).toFixed(3)}%`, pp = (p: number) => (100 * p).toFixed(3);
const summary = `# Estabilidad entre carteras y presupuestos\n\n${dates.length} snapshots V13.3, tres semillas por snapshot: 21 parejas y ${metadata.totalSyntheticDraws.toLocaleString("en-US")} sorteos sintéticos uniformes nuevos. Ningún resultado real se usa para diseñar o evaluar predicción.\n\n## Diferencia de cobertura 7+ al mismo costo\n\n| Jugadas | Aleatorio | Heurística cobertura | Diferencia en pp | Intervalo cluster ajustado, pp | Fechas positivas | Supera puerta exploratoria |\n| --- | ---: | ---: | ---: | --- | ---: | --- |\n${cluster.map(r => `| ${r.budget} | ${pct(r.randomRate)} | ${pct(r.coverageRate)} | ${pp(r.difference)} | ${r.adjustedClusterInterval.map(pp).join(" a ")} | ${r.positiveDates}/${r.snapshots} | ${r.passesExploratoryGate ? "Sí" : "No"} |`).join("\n")}\n\nBootstrap exploratorio por siete fechas, agrupando semillas antes del remuestreo. Intervalos nominales98.333% por presupuesto, ajuste Bonferroni de tres comparaciones. Pocos clusters y selección fija de snapshots: no es una garantía de generalización ni precisión certificada. Error Monte Carlo pareado por réplica y diferencias por fecha están en report.json.\n\n## Presupuesto: promedio de estas carteras\n\n| Jugadas | Costo RD$ | Alguna7+ con heurística | Cobertura7+ retenida | Alguna8+ | Frecuencia de pérdida | Neto esperado RD$ |\n| --- | ---: | ---: | ---: | ---: | ---: | ---: |\n${budgetSummary.map(r => `| ${r.budget} | ${r.cost} | ${pct(r.coverageSevenRate)} | ${pct(r.coverageRetainedSeven)} | ${pct(r.coverageEightRate)} | ${pct(r.coverageLossRate)} | ${r.expectedNet.toFixed(2)} |`).join("\n")}\n\n## Decisión\n\n${decision}.\n\nLa puerta exige +0.1pp medio, límite inferior ajustado positivo, al menos5/7 fechas positivas y ninguna fecha peor que−0.1pp. Ningún resultado autoriza adopción automática. Reducir costo baja pérdida absoluta esperada, no el ROI uniforme modelado (${pct(economics.expectedRoi)}). Tabla del snapshot, sin certificación oficial ni retenciones.\n\nNo se cambió la heurística, las semillas ni la muestra después de evaluar. A200 ambos métodos son idénticos en todos los escenarios. Snapshot y órdenes exactos preservados; sin cambios operativos.\n`;
await writeFile(resolve(out, "SUMMARY.md"), summary); console.log(summary); console.log(`Saved ${out}`);

import { randomStream } from "./kino-bowl-lab.ts";

export type StabilityRow = { date: string; seed: number; budget: number; randomRate: number; coverageRate: number };
/** Group seeds by snapshot first. Intervals describe this selected set, not a random sample of all portfolios. */
export function summarizeStability(rows: StabilityRow[], bootstrapSeed: string, replicates = 6000) {
  if (!rows.length || !Number.isSafeInteger(replicates) || replicates < 100) throw new Error("Insufficient bootstrap input");
  const seen = new Set<string>();
  for (const row of rows) {
    if (!row.date || !Number.isSafeInteger(row.seed) || !Number.isSafeInteger(row.budget) || row.budget < 1 || row.budget > 200 || ![row.randomRate, row.coverageRate].every(p => Number.isFinite(p) && p >= 0 && p <= 1)) throw new Error("Invalid stability row");
    const key = `${row.date}/${row.seed}/${row.budget}`;
    if (seen.has(key)) throw new Error("Duplicate replicate"); seen.add(key);
  }
  const budgets = [...new Set(rows.map(r => r.budget))].sort((a, b) => a - b);
  const dates = [...new Set(rows.map(r => r.date))].sort();
  if (dates.length < 2) throw new Error("Need multiple snapshot dates");
  // Keep the same cluster resamples across budgets for their shared dependence.
  const random = randomStream(bootstrapSeed);
  const samples = Array.from({ length: replicates }, () => dates.map(() => Math.floor(random() * dates.length)));
  const alpha = 0.05 / budgets.length;
  return budgets.map(budget => {
    const byDate = dates.map(date => {
      const group = rows.filter(r => r.budget === budget && r.date === date);
      if (!group.length) throw new Error("Missing snapshot/budget");
      const mean = (f: (r: StabilityRow) => number) => group.reduce((s, r) => s + f(r), 0) / group.length;
      return { date, seeds: group.length, randomRate: mean(r => r.randomRate), coverageRate: mean(r => r.coverageRate), difference: mean(r => r.coverageRate - r.randomRate) };
    });
    const deltas = byDate.map(r => r.difference), n = dates.length;
    const distribution = samples.map(sample => sample.reduce((s, i) => s + deltas[i], 0) / n).sort((a, b) => a - b);
    const quantile = (p: number) => {
      const i = p * (distribution.length - 1), lo = Math.floor(i), hi = Math.ceil(i);
      return distribution[lo] + (distribution[hi] - distribution[lo]) * (i - lo);
    };
    const difference = deltas.reduce((s, d) => s + d, 0) / n, interval = [quantile(alpha / 2), quantile(1 - alpha / 2)];
    const positiveDates = deltas.filter(d => d > 0).length;
    // Prior pilot gate only; never authorization to adopt.
    const passesExploratoryGate = difference >= 0.001 && interval[0] > 0 && positiveDates >= Math.ceil(0.7 * n) && Math.min(...deltas) >= -0.001;
    return { budget, snapshots: n, subsetReplicates: rows.filter(r => r.budget === budget).length, byDate,
      randomRate: byDate.reduce((s, r) => s + r.randomRate, 0) / n, coverageRate: byDate.reduce((s, r) => s + r.coverageRate, 0) / n,
      difference, positiveDates, minDateDifference: Math.min(...deltas), maxDateDifference: Math.max(...deltas), adjustedClusterInterval: interval,
      bootstrapReplicates: replicates, comparisons: budgets.length, perBudgetCoverage: 1 - alpha, passesExploratoryGate };
  });
}

import { jointThresholdProbability } from "./kino-math.ts";
import { validateExperimentPortfolio } from "./kino-experiment-strategies.ts";
import { randomStream } from "./kino-bowl-lab.ts";

/** Nested subsets of a saved portfolio; never uses winning outcomes. */
export function orderBudgetTickets(tickets: number[][], mode: "random" | "coverage", seed: string) {
  validateExperimentPortfolio(tickets);
  const random = randomStream(seed), remaining = Array.from({ length: 200 }, (_, i) => i);
  for (let i = 199; i > 0; i--) { const j = Math.floor(random() * (i + 1)); [remaining[i], remaining[j]] = [remaining[j], remaining[i]]; }
  if (mode === "random") return remaining;
  const q = Array.from({ length: 11 }, (_, overlap) => jointThresholdProbability({ universe: 84, drawSize: 20, ticketSize: 10, threshold: 7 }, overlap));
  const flags = tickets.map(t => new Set(t)), exposure = Array<number>(85).fill(0), scores = Array<number>(200).fill(0), order: number[] = [];
  while (remaining.length) {
    // Primary: minimize added pairwise intersection probability for the 7+ event.
    // Secondary: minimize increase in squared exposure. Ties follow fixed shuffled order.
    let best = 0;
    const exposureIncrement = (i: number) => tickets[i].reduce((s, n) => s + 2 * exposure[n] + 1, 0);
    for (let k = 1; k < remaining.length; k++) {
      const a = remaining[k], b = remaining[best];
      if (scores[a] < scores[b] || (scores[a] === scores[b] && exposureIncrement(a) < exposureIncrement(b))) best = k;
    }
    const next = remaining.splice(best, 1)[0]; order.push(next);
    tickets[next].forEach(n => exposure[n]++);
    remaining.forEach(i => { scores[i] += q[tickets[i].filter(n => flags[next].has(n)).length]; });
  }
  return order;
}

export function prepareBudgetEvaluator(tickets: number[][], budgets: readonly number[], prizes: readonly { hits: number; amount: number }[]) {
  validateExperimentPortfolio(tickets);
  if (!budgets.length || budgets.some((n, i) => !Number.isInteger(n) || n < 1 || n > 200 || (i > 0 && n <= budgets[i - 1]))) throw new Error("Budgets must increase within 1..200");
  const copied = tickets.map(t => [...t]), payout = Array<number>(11).fill(0);
  for (const p of prizes) {
    if (!Number.isInteger(p.hits) || p.hits < 0 || p.hits > 10 || !Number.isFinite(p.amount) || p.amount < 0) throw new Error("Invalid prize");
    payout[p.hits] = p.amount;
  }
  return (winning: number[]) => {
    if (winning.length !== 20 || new Set(winning).size !== 20 || winning.some(n => !Number.isInteger(n) || n < 1 || n > 84)) throw new Error("Invalid winning draw");
    const flags = new Uint8Array(85); winning.forEach(n => flags[n] = 1);
    const results: { tickets: number; maxHits: number; gross: number }[] = [];
    let gross = 0, maxHits = 0, next = 0;
    for (let i = 0; i < budgets[budgets.length - 1]; i++) {
      const hits = copied[i].reduce((s, n) => s + flags[n], 0);
      maxHits = Math.max(maxHits, hits); gross += payout[hits];
      if (i + 1 === budgets[next]) { results.push({ tickets: i + 1, maxHits, gross }); next++; }
    }
    return results;
  };
}

import { choose, portfolioCoverageBounds } from "./kino-math.ts";
import { validateExperimentPortfolio } from "./kino-experiment-strategies.ts";

export function exactTicketEconomics(prizes: readonly { hits: number; amount: number }[], ticketCost = 25) {
  if (!Number.isFinite(ticketCost) || ticketCost <= 0 || new Set(prizes.map(p => p.hits)).size !== prizes.length || prizes.some(p => !Number.isInteger(p.hits) || p.hits < 0 || p.hits > 10 || !Number.isFinite(p.amount) || p.amount < 0)) throw new Error("Invalid economics");
  const probabilities = Array.from({ length: 11 }, (_, k) => Number(choose(10, k) * choose(74, 20 - k)) / Number(choose(84, 20)));
  const gross = prizes.reduce((s, p) => s + p.amount * probabilities[p.hits], 0);
  return { probabilities, ticketCost, expectedGrossPerTicket: gross, expectedNetPerTicket: gross - ticketCost, expectedRoi: gross / ticketCost - 1 };
}
export function portfolioStructure(tickets: number[][]) {
  validateExperimentPortfolio(tickets);
  const exposure = Array<number>(84).fill(0), overlapHistogram = Array<number>(11).fill(0);
  tickets.forEach(t => t.forEach(n => exposure[n - 1]++));
  for (let a = 0; a < tickets.length; a++) {
    const set = new Set(tickets[a]);
    for (let b = a + 1; b < tickets.length; b++) overlapHistogram[tickets[b].filter(n => set.has(n)).length]++;
  }
  return { exposure, exposureMin: Math.min(...exposure), exposureMax: Math.max(...exposure), overlapHistogram,
    meanOverlap: overlapHistogram.reduce((s, n, k) => s + n * k, 0) / 19900,
    highOverlapPairs7: overlapHistogram.slice(7).reduce((s, n) => s + n, 0),
    sevenBounds: portfolioCoverageBounds({ universe: 84, drawSize: 20, ticketSize: 10, threshold: 7 }, tickets),
    eightBounds: portfolioCoverageBounds({ universe: 84, drawSize: 20, ticketSize: 10, threshold: 8 }, tickets) };
}

/** Offline pool-coverage research. No operational storage or prize calculations. */
export const BOWL_VERSION = "kino-bowl-lab-v1";
export type LabDraw = { date: string; numbers: number[] };
export const policies = ["uniform", "range10", "frequency"] as const;
export type Policy = typeof policies[number];
export function randomStream(seed: string) {
  let state = 2166136261;
  for (const c of seed) state = Math.imul(state ^ c.charCodeAt(0), 16777619);
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = Math.imul(state ^ (state >>> 15), state | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
export function choose(n: number, k: number): number {
  if (!Number.isInteger(n) || !Number.isInteger(k) || n < 0) throw new Error("Invalid combination");
  if (k < 0 || k > n) return 0;
  let value = 1;
  for (let i = 1; i <= Math.min(k, n - k); i++) value = value * (n - i + 1) / i;
  return value;
}
export function exactOverlap(n = 84, winners = 20, selected = 20) {
  if (![n, winners, selected].every(Number.isInteger) || n < 1 || winners < 0 || selected < 0 || winners > n || selected > n) throw new Error("Invalid population");
  return Array.from({ length: selected + 1 }, (_, k) => choose(winners, k) * choose(n - winners, selected - k) / choose(n, selected));
}
/** Rejection sampling: each next accepted ball has weight / remaining total weight. */
export function sampleBalls(random: () => number, weights: readonly number[], count = 20) {
  if (!Number.isInteger(count) || count < 0 || count > weights.length || weights.some(w => !Number.isFinite(w) || w <= 0)) throw new Error("Invalid bowl");
  const max = Math.max(...weights), seen = new Uint8Array(weights.length), result: number[] = [];
  while (result.length < count) {
    const i = Math.floor(random() * weights.length);
    if (!seen[i] && random() * max < weights[i]) { seen[i] = 1; result.push(i + 1); }
  }
  return result;
}
const uniformWeights = Array<number>(84).fill(1);
export function priorModel(history: readonly LabDraw[], target: string) {
  const prior = history.filter(d => d.date < target).sort((a, b) => a.date.localeCompare(b.date));
  const counts = Array<number>(84).fill(0);
  for (const d of prior) for (const n of d.numbers) counts[n - 1]++;
  // 30 equivalent uniform draws; no parameter tuning on outcomes.
  const weights = counts.map(c => (c + 30 * 20 / 84) / (prior.length + 30));
  const ranges = [0, 1, 2].map(r => weights.slice(r * 28, (r + 1) * 28).reduce((s, w) => s + w, 0));
  const dominant = ranges.indexOf(Math.max(...ranges)); // tie: lower range
  return { weights, dominant, priorCount: prior.length, priorLastDate: prior.at(-1)?.date ?? null };
}
export function selectPool(policy: Policy, random: () => number, model: ReturnType<typeof priorModel>) {
  if (policy === "uniform") return sampleBalls(random, uniformWeights);
  if (policy === "frequency") return sampleBalls(random, model.weights);
  return [0, 1, 2].flatMap(r => sampleBalls(random, Array<number>(28).fill(1), r === model.dominant ? 10 : 5).map(n => n + r * 28));
}
export function overlap(a: readonly number[], b: readonly number[]) {
  const present = new Set(b);
  return a.reduce((s, n) => s + Number(present.has(n)), 0);
}
export function wilson(success: number, total: number) {
  if (total <= 0) return null;
  const p = success / total, z = 1.959963984540054, z2 = z * z;
  const center = (p + z2 / (2 * total)) / (1 + z2 / total);
  const half = z * Math.sqrt(p * (1 - p) / total + z2 / (4 * total * total)) / (1 + z2 / total);
  return [center - half, center + half];
}
export function summarize(histogram: number[], uncertainty = true) {
  const draws = histogram.reduce((s, n) => s + n, 0), atLeast10 = histogram.slice(10).reduce((s, n) => s + n, 0);
  return { draws, histogram, mean: histogram.reduce((s, n, k) => s + n * k, 0) / draws,
    atLeast10, rate10: atLeast10 / draws, wilson95: uncertainty ? wilson(atLeast10, draws) : null };
}
export function simulateBowl(iterations: number, seed: string, model: ReturnType<typeof priorModel>, bias = 0) {
  if (!Number.isSafeInteger(iterations) || iterations < 1 || !Number.isFinite(bias) || bias < 0 || bias > 1) throw new Error("Invalid simulation budget/bias");
  const drawRandom = randomStream(`${seed}/draw`);
  const streams = policies.map(p => randomStream(`${seed}/selection/${p}`));
  const histograms = policies.map(() => Array<number>(21).fill(0));
  const weights = uniformWeights.map((w, i) => w + (Math.floor(i / 28) === model.dominant ? bias : 0));
  // Intentional synthetic range advantage, fixed before draws; never inferred physics.
  for (let i = 0; i < iterations; i++) {
    const pools = policies.map((p, k) => selectPool(p, streams[k], model));
    const winning = sampleBalls(drawRandom, weights);
    pools.forEach((pool, k) => histograms[k][overlap(pool, winning)]++);
  }
  return { iterations, seed, bias, policies: Object.fromEntries(policies.map((p, k) => [p, summarize(histograms[k])])) };
}
/** Finite real dates, not synthetic independent evidence. Repetitions average policy randomness only. */
export function walkForward(history: readonly LabDraw[], seed: string, repetitions = 100) {
  if (!Number.isSafeInteger(repetitions) || repetitions < 1) throw new Error("Invalid repetitions");
  const ordered = [...history].sort((a, b) => a.date.localeCompare(b.date));
  return ordered.filter(d => priorModel(ordered, d.date).priorCount >= 30).map(draw => {
    const model = priorModel(ordered, draw.date);
    const results = Object.fromEntries(policies.map(policy => {
      const histogram = Array<number>(21).fill(0);
      for (let r = 0; r < repetitions; r++) histogram[overlap(selectPool(policy, randomStream(`${seed}/${draw.date}/${policy}/${r}`), model), draw.numbers)]++;
      return [policy, summarize(histogram, false)];
    }));
    return { date: draw.date, priorCount: model.priorCount, priorLastDate: model.priorLastDate, dominantRange: model.dominant, results };
  });
}

/** Offline combinatorics for a uniform draw without replacement. Never a predictor. */
export interface KinoProbabilityModel {
  universe: number;
  drawSize: number;
  ticketSize: number;
  threshold: number;
}

export function choose(n: number, r: number): bigint {
  if (!Number.isSafeInteger(n) || !Number.isSafeInteger(r) || n < 0) throw new Error("Invalid combination arguments");
  if (r < 0 || r > n) return 0n;
  let result = 1n;
  for (let i = 1; i <= Math.min(r, n - r); i++) result = result * BigInt(n - i + 1) / BigInt(i);
  return result;
}

function validate(model: KinoProbabilityModel) {
  const { universe: n, drawSize: d, ticketSize: t, threshold: k } = model;
  if (![n, d, t, k].every(Number.isSafeInteger) || n < 1 || d < 0 || d > n || t < 0 || t > n || k < 0 || k > t) {
    throw new Error("Invalid uniform-draw model");
  }
}

function ratio(numerator: bigint, denominator: bigint) {
  if (!numerator) return 0;
  const n = Number(numerator), d = Number(denominator);
  if (Number.isFinite(n) && Number.isFinite(d)) return n / d;
  // Preserve significant figures instead of truncating probabilities below1e-18.
  const ns = numerator.toString(), ds = denominator.toString();
  const mantissa = (text: string) => Number(text.slice(0, 16)) / 10 ** (Math.min(16, text.length) - 1);
  return Number(`${mantissa(ns) / mantissa(ds)}e${ns.length - ds.length}`);
}

export function thresholdProbability(model: KinoProbabilityModel): number {
  validate(model);
  const { universe: n, drawSize: d, ticketSize: t, threshold: k } = model;
  let count = 0n;
  for (let h = k; h <= Math.min(t, d); h++) count += choose(t, h) * choose(n - t, d - h);
  return ratio(count, choose(n, d));
}

/** Two equal-size tickets sharing overlap numbers; sum over shared and exclusive hits. */
export function jointThresholdProbability(model: KinoProbabilityModel, overlap: number): number {
  validate(model);
  const { universe: n, drawSize: d, ticketSize: t, threshold: k } = model;
  if (!Number.isSafeInteger(overlap) || overlap < Math.max(0, 2 * t - n) || overlap > t) throw new Error("Invalid ticket overlap");
  const exclusive = t - overlap;
  const outside = n - 2 * t + overlap;
  let count = 0n;
  for (let shared = 0; shared <= Math.min(overlap, d); shared++) {
    for (let a = Math.max(0, k - shared); a <= exclusive; a++) {
      for (let b = Math.max(0, k - shared); b <= exclusive; b++) {
        count += choose(overlap, shared) * choose(exclusive, a) * choose(exclusive, b) * choose(outside, d - shared - a - b);
      }
    }
  }
  return ratio(count, choose(n, d));
}

/** Analytical bounds evaluated numerically, not estimates or achievable targets.
 * Combinatorial counts are exact; returned ratios/bounds have floating-point error.
 * Floating-point summation error can accumulate over ticket pairs: not interval-certified.
 */
export function portfolioCoverageBounds(model: KinoProbabilityModel, tickets: readonly (readonly number[])[]) {
  validate(model);
  const sets = tickets.map(ticket => {
    const set = new Set(ticket);
    if (ticket.length !== model.ticketSize || set.size !== ticket.length || ticket.some(n => !Number.isSafeInteger(n) || n < 1 || n > model.universe)) {
      throw new Error("Invalid ticket");
    }
    return set;
  });
  const probabilities = Array.from({ length: model.ticketSize + 1 }, (_, overlap) =>
    overlap < Math.max(0, 2 * model.ticketSize - model.universe) ? 0 : jointThresholdProbability(model, overlap));
  let pairIntersectionSum = 0;
  for (let i = 0; i < tickets.length; i++) {
    for (let j = i + 1; j < tickets.length; j++) {
      pairIntersectionSum += probabilities[tickets[i]!.filter(n => sets[j]!.has(n)).length]!;
    }
  }
  const marginal = thresholdProbability(model);
  const expectedQualifying = tickets.length * marginal;
  return {
    marginal, expectedQualifying, pairIntersectionSum,
    unionUpper: Math.min(1, expectedQualifying),
    bonferroniLower: Math.max(0, expectedQualifying - pairIntersectionSum),
    secondMomentLower: expectedQualifying ? expectedQualifying ** 2 / (expectedQualifying + 2 * pairIntersectionSum) : 0,
  };
}

import { buildKinoV133Numbers } from "./super-kino-v133.ts";

/** Offline-only strategies. No historical outcome, frequency or delay is consumed. */
export const experimentModes = ["uniform", "balanced", "v133-production"] as const;
export type ExperimentMode = typeof experimentModes[number];

const universe = Array.from({ length: 84 }, (_, index) => index + 1);
const ticketCount = 200;
const ticketSize = 10;

function randomFor(seed: string) {
  let state = 2166136261;
  for (const character of seed) state = Math.imul(state ^ character.charCodeAt(0), 16777619);
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let value = Math.imul(state ^ (state >>> 15), state | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

function shuffle<T>(values: readonly T[], random: () => number) {
  const result = [...values];
  for (let index = result.length - 1; index > 0; index--) {
    const other = Math.floor(random() * (index + 1));
    [result[index], result[other]] = [result[other]!, result[index]!];
  }
  return result;
}

function uniform(seed: string) {
  const random = randomFor(`kino-experiment-uniform-v1:${seed}`);
  const tickets: number[][] = [];
  const seen = new Set<string>();
  while (tickets.length < ticketCount) {
    const ticket = shuffle(universe, random).slice(0, ticketSize).sort((a, b) => a - b);
    const key = ticket.join(",");
    if (!seen.has(key)) { tickets.push(ticket); seen.add(key); }
  }
  return tickets;
}

function balanced(seed: string) {
  // 2,000 slots: 68 numbers occur 24 times and 16 occur 23 times.
  // Mandatory picks keep every remaining quota feasible; other picks are
  // weighted by remaining quota. This is not uniform over balanced portfolios
  // and does not optimize against historical or synthetic winning results.
  for (let retry = 0; retry < 32; retry++) {
    const random = randomFor(`kino-experiment-balanced-v1:${seed}:${retry}`);
    const extra = new Set(shuffle(universe, random).slice(0, 68));
    const remaining = [0, ...universe.map(number => 23 + Number(extra.has(number)))];
    const tickets: number[][] = [];
    const seen = new Set<string>();
    for (let round = 0; round < ticketCount; round++) {
      const roundsLeft = ticketCount - round;
      const ticket = universe.filter(number => remaining[number] === roundsLeft);
      const pool = universe.filter(number => remaining[number]! > 0 && !ticket.includes(number));
      if (ticket.length > ticketSize) break;
      while (ticket.length < ticketSize && pool.length) {
        let point = random() * pool.reduce((sum, number) => sum + remaining[number]!, 0);
        let position = 0;
        for (; position < pool.length - 1; position++) {
          point -= remaining[pool[position]!]!;
          if (point < 0) break;
        }
        ticket.push(pool.splice(position, 1)[0]!);
      }
      ticket.sort((a, b) => a - b);
      const key = ticket.join(",");
      if (ticket.length !== ticketSize || seen.has(key)) break;
      seen.add(key);
      ticket.forEach(number => remaining[number]!--);
      tickets.push(ticket);
    }
    if (tickets.length === ticketCount && remaining.every(value => value === 0)) return tickets;
  }
  throw new Error("No se pudo completar la cartera experimental equilibrada.");
}

export function validateExperimentPortfolio(tickets: readonly (readonly number[])[]) {
  if (tickets.length !== ticketCount) throw new Error("La cartera experimental debe tener 200 jugadas.");
  const seen = new Set<string>();
  for (const ticket of tickets) {
    if (ticket.length !== ticketSize || new Set(ticket).size !== ticketSize ||
        ticket.some(number => !Number.isInteger(number) || number < 1 || number > 84)) {
      throw new Error("Cada jugada experimental debe tener 10 números únicos entre 1 y 84.");
    }
    const key = [...ticket].sort((a, b) => a - b).join(",");
    if (seen.has(key)) throw new Error("La cartera experimental contiene jugadas duplicadas.");
    seen.add(key);
  }
}

export function buildExperimentPortfolio(mode: string, seed: string): number[][] {
  if (!experimentModes.includes(mode as ExperimentMode)) throw new Error(`Estrategia experimental desconocida: ${mode}`);
  // V13.3's targetDate argument is only a seed label in its implementation.
  // Passing this experimental label invokes the exact production algorithm,
  // not a frozen historical portfolio and not a claim of historical issuance.
  const tickets = mode === "v133-production" ? buildKinoV133Numbers(seed)
    : mode === "balanced" ? balanced(seed) : uniform(seed);
  validateExperimentPortfolio(tickets);
  return tickets;
}

